/** Project a coordinate into the viewBox. Returns null for unusable values. */
export function projectPoint(
  lat: number | null | undefined,
  lon: number | null | undefined
): { x: number; y: number } | null {
  if (
    typeof lat !== "number" ||
    typeof lon !== "number" ||
    !Number.isFinite(lat) ||
    !Number.isFinite(lon) ||
    lat < -90 ||
    lat > 90 ||
    lon < -180 ||
    lon > 180
  ) {
    return null;
  }
  return {
    x: ((lon + 180) / 360) * 1000,
    y: ((90 - lat) / 180) * 500,
  };
}
